create table if not exists public.admin_user_controls (id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,status text not null default 'active' check (status in ('active','suspended','blocked','deleted')),access jsonb not null default '{}'::jsonb,vendor_margin_cut numeric not null default 0,seller_margin_cut numeric not null default 0,notes text,updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admin_rules (id uuid primary key default gen_random_uuid(),name text not null,description text,role text check (role in ('seller','vendor','all')),enabled boolean not null default true,conditions jsonb not null default '{}'::jsonb,actions jsonb not null default '{}'::jsonb,priority integer not null default 100,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.admin_audit_logs (id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,before_data jsonb,after_data jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.kyc_profiles drop constraint if exists kyc_profiles_status_check;
alter table public.kyc_profiles add constraint kyc_profiles_status_check check (status in ('pending','submitted','verified','action_required','rejected'));
alter table public.admin_user_controls enable row level security;
alter table public.admin_rules enable row level security;
alter table public.admin_audit_logs enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin') $$;
revoke execute on function public.is_admin() from public;
grant execute on function public.is_admin() to authenticated;
create policy "admins manage user controls" on public.admin_user_controls for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage rules" on public.admin_rules for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins read audit" on public.admin_audit_logs for select to authenticated using (public.is_admin());
create policy "admins insert audit" on public.admin_audit_logs for insert to authenticated with check (public.is_admin());
drop policy if exists "admins full control" on public.profiles; create policy "admins full control" on public.profiles for all to authenticated using (public.is_admin()) with check (public.is_admin());
